(()=>{'use strict';const editor=document.getElementById('editor');const editorUrl='index.html?embed=1&proto=json&spin=1&configure=1&libraries=0&plugins=0&offline=1&local=1&picker=0&lang=zh';let nonce='',configured=null,pendingLoad=null,editorReady=false,sequence=0;const id=()=>('evt_'+String(++sequence).padStart(16,'0'));const send=(event,payload,requestId)=>{if(!nonce)return;parent.postMessage({protocol:1,event,nonce,requestId:requestId||id(),payload},'*')};const forward=value=>editor.contentWindow&&editor.contentWindow.postMessage(JSON.stringify(value),'*');const configure=()=>forward({action:'configure',config:{css:'',libraries:[],plugins:[],customFonts:[],fontCss:''}});const load=()=>forward({action:'load',xml:(pendingLoad&&pendingLoad.payload&&pendingLoad.payload.xml)||'',autosave:1});addEventListener('message',event=>{if(event.source===parent){const value=event.data;if(!value||value.protocol!==1||typeof value.nonce!=='string'||typeof value.requestId!=='string')return;nonce=value.nonce;if(value.action==='configure'){configured=value;if(editorReady){configure();send('ready',{},value.requestId)}return}if(value.action==='load'){pendingLoad=value;if(editorReady)load();return}if(value.action==='export'&&editorReady)forward({action:'export',format:(value.payload&&value.payload.format)||'xml',spinKey:'export'})}else if(event.source===editor.contentWindow){let value=event.data;try{if(typeof value==='string')value=JSON.parse(value)}catch{return}if(!value||typeof value.event!=='string')return;if(value.event==='configure'){configure();return}if(value.event==='init'){editorReady=true;if(pendingLoad)load();send('ready',{},configured&&configured.requestId);return}if(value.event==='save'||value.event==='autosave'){if(typeof value.xml==='string')send('save',{xml:value.xml},id());return}if(value.event==='export'){send('export',{data:typeof value.data==='string'?value.data:value.xml,format:value.format},id());return}if(value.event==='exit')return;if(value.event==='error')send('error',{message:String(value.message||'diagrams.net error')},id())}});editor.src=editorUrl})()
